package run.ikaros.photo; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/photos/{photoId}/metadata") public class PhotoMetadataController{private final PhotoMetadataService service;public PhotoMetadataController(PhotoMetadataService s){service=s;}@PutMapping public Mono<PhotoView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID photoId,@Valid@RequestBody UpdatePhotoMetadataRequest r){return service.update(o,photoId,r);}@GetMapping public Mono<PhotoView> get(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID photoId){return service.get(o,photoId);}}
